/* generated by tools/patterns/import.py; edit patterns/ (the .mid or .musicxml files:
   patterns/README.md), then run tools/patterns/import.sh. Never edit this file. */

#ifndef SONG_PATTERNS_GEN_H
#define SONG_PATTERNS_GEN_H
#include <stdint.h>
#include "library.h"

/* Each *_STATUS runs parallel to its table: 1 approved (the roll draws it), 0 candidate (the workbench
   only, until Sam approves it: patterns/status.json), 2 retired (never drawn). The comp rhythms and the
   strum fills are fixed entries, always approved. */

/* drums (LIB_PATTERNS) and progressions (LIB_PROGS): the types and the tables in library.h */
extern const uint8_t LIB_PATTERNS_STATUS[];
extern const uint8_t LIB_PROGS_STATUS[];

/* the keys' held, half-note, held-on-2 (and 4) and light-eighths comping (harmony.c): strikes in a bar,
   `later_vel_pct` the later strikes' velocity in percent of the first's; len is in 16ths (held: written a bar, the
   engine holds the chord; a strike as long as the gap to the next, or to the bar's end, is held to it) */
typedef struct {
    uint8_t vel_lo, vel_hi;
    uint8_t n;                          /* strikes */
    uint8_t step[8], len[8];
    uint8_t later_vel_pct;
} patterns_comp_t;
/* the stabs: one on `first`, the second on the first of `second` the kick leaves free; over a kick of more
   than `busy_over` hits a bar, `busy_steps` (a mask). len: the written length (the engine strikes 60% of a
   quarter) */
typedef struct {
    uint8_t vel_lo, vel_hi;
    uint8_t first;
    uint8_t n;                          /* second-stab candidates, tried in order */
    uint8_t second[4];
    uint8_t len;
    uint8_t busy_over;
    uint16_t busy_steps;
} patterns_stabs_t;
extern const patterns_comp_t COMP_HELD, COMP_HALF, COMP_HELD2, COMP_LIGHT8, COMP_HELD24;
extern const patterns_stabs_t COMP_STABS;
/* the comp rhythms past those six (patterns/comp-rhythms' added files; harmony.c's CS_PAT), one bar of
   strikes each. The host's and the workbench's builds hold every entry (a candidate plays when the comp_pat
   override forces it); the firmware only the approved, the ones the roll draws: a candidate costs it
   nothing */
#if defined PLAT_HOST || defined __EMSCRIPTEN__ || defined __APPLE__ || defined __linux__
#define COMP_PAT_ALL 1
#define COMP_NPAT 3
#else
#define COMP_PAT_ALL 0
#define COMP_NPAT 3
#endif
#if COMP_NPAT
extern const patterns_comp_t COMP_PAT[COMP_NPAT];
#endif
#if COMP_PAT_ALL && COMP_NPAT
extern const uint8_t COMP_PAT_STATUS[COMP_NPAT];
#define COMP_PAT_APPROVED(i) (COMP_PAT_STATUS[i] == 1)
#else
#define COMP_PAT_APPROVED(i) 1                 /* (the firmware's are all approved) */
#endif

/* strum.c's patterns (16 steps; 32 for a two-bar one) and the ballad's fill-bar variant */
#define STRUM_NPAT 14
extern const char *const STRUM_PAT[STRUM_NPAT];
extern const uint8_t STRUM_PAT_STATUS[STRUM_NPAT];
extern const char STRUM_BALLAD_FILL[];
/* the fill-bar figures a strummed song draws one of (16 steps): step back, a strike on 1 and space for the
   drum fill, and drive, pushing into the change; [0] every pattern's but the ballad's (its own
   fill) and the bossa's, [1] the bossa's (its thumb and pinches) */
#define STRUM_NFILL 2
extern const char *const STRUM_FILL_STEP[STRUM_NFILL];
extern const char *const STRUM_FILL_DRIVE[STRUM_NFILL];

#endif
